    @ElementCollection(fetch = EAGER)
    @CollectionTable(name = "consignment_checkin", joinColumns = @JoinColumn(name = "consignment_id"))
    @OrderColumn(name = "checkin_index")
    public List<Checkin> getCheckins() {
